import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.CZo9GF0W.js";const f=JSON.parse('{"title":"SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/sqlite.md","filePath":"recipes/sqlite.md","lastUpdated":1789060268000}'),d={name:"recipes/sqlite.md"};function r(n,t,s,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="sqlite" tabindex="-1">SQLite <a class="header-anchor" href="#sqlite" aria-label="Permalink to &quot;SQLite&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>anything</td></tr><tr><td>Database file</td><td>the path to a <code>.sqlite</code> / <code>.db</code> file, or <code>:memory:</code></td></tr><tr><td>Environment</td><td><code>dev</code>, usually</td></tr><tr><td>Read-only</td><td>tick it to open a file you only want to look at</td></tr></tbody></table><p>There is no host, port or password: SQLite is a file, and the connection form shows the fields that exist rather than greying out the ones that do not.</p><p><code>:memory:</code> gives a scratch database that is never written to disk — useful for trying something out, and gone when you disconnect.</p><p>The engine is <code>node-sqlite3-wasm</code>, compiled to WebAssembly and shipped inside the VSIX. Nothing to install, and one build works on every platform.</p><h2 id="what-is-different" tabindex="-1">What is different <a class="header-anchor" href="#what-is-different" aria-label="Permalink to &quot;What is different&quot;">​</a></h2><p>SQLite exists in Pitta partly to prove that capability flags work: the UI hides what this engine cannot do instead of offering a control that fails.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Schemas</td><td>none — the tree goes straight from the connection to tables</td></tr><tr><td>Multiple databases</td><td>one file per connection</td></tr><tr><td>Server-side cursors</td><td>none; results are read in full within the memory guard</td></tr><tr><td>Query cancellation</td><td>none — the command is hidden rather than offered and useless</td></tr><tr><td><code>EXPLAIN</code> plan view</td><td>not offered</td></tr><tr><td>Transactional DDL</td><td>yes</td></tr><tr><td>Schema diff and migration</td><td>not offered</td></tr><tr><td><code>LISTEN</code> / pub-sub</td><td>none</td></tr><tr><td>SSH tunnel</td><td>not applicable</td></tr></tbody></table><p>If any of those appear enabled and then fail, that is a capability-gating bug and worth reporting.</p><h2 id="row-identity" tabindex="-1">Row identity <a class="header-anchor" href="#row-identity" aria-label="Permalink to &quot;Row identity&quot;">​</a></h2><p>SQLite tables have <code>rowid</code> unless declared <code>WITHOUT ROWID</code>, so a table with no primary key is still editable through the row-id fallback — Pitta says when it is using it. A <code>WITHOUT ROWID</code> table with no primary key cannot be edited, and the grid says so rather than failing on apply.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><p>SQLite has storage classes rather than declared types, and a column will hold whatever you put in it. Pitta reads the declared type for the affinity and the editor, and shows the value&#39;s actual storage class. A <code>DECIMAL</code> column declared in a SQLite schema is stored as text or as a float depending on what was inserted; Pitta shows what is really there rather than what the declaration implies.</p><h2 id="reading-a-file-over-remote-ssh" tabindex="-1">Reading a file over Remote-SSH <a class="header-anchor" href="#reading-a-file-over-remote-ssh" aria-label="Permalink to &quot;Reading a file over Remote-SSH&quot;">​</a></h2><p>The path is resolved on the machine VS Code&#39;s workspace is on. A file on your laptop is not reachable from a Remote-SSH window; copy it across, or open a local window for that connection. See <a href="/pitta-db/guide/remote">Remote development</a>.</p><h2 id="locking" tabindex="-1">Locking <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;Locking&quot;">​</a></h2><p>SQLite takes a write lock on the file. Another process holding one — an application, another editor — will make writes fail with <code>SQLITE_BUSY</code>. That is the file&#39;s own concurrency model rather than something Pitta can queue around.</p>',17)])])}const m=e(d,[["render",r]]);export{f as __pageData,m as default};
